input.command:
census() { for f in $(find "$1" -name '*.lean' | sort); do n=$(grep -cPn '(?<!`)\bsorry\b(?!`)' "$f" 2>/dev/null); [ "$n" -gt 0 ] && { echo "--- $f ($(wc -l < $f) lines): $n candidate"; grep -nP '(?<!`)\bsorry\b(?!`)' "$f" | head -12; }; done; }
echo "########## SubProjects/Albanese ##########"; census /home/axel/LeanAlgebraicGeometry-Horizon/SubProjects/Albanese/AlgebraicJacobian/Albanese
echo "########## AJC Albanese ##########"; census /home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge/AlgebraicJacobian/Albanese
